all_sent = []
page = 0
while True:
    resp = apis.venmo.show_sent_payment_requests(access_token=access_token, page_index=page, page_limit=20)
    if not resp:
        break
    all_sent.extend(resp)
    if len(resp) < 20:
        break
    page += 1

# Filter for created_at on 2023-05-19 and time >= 18:00
evening_requests = []
for req in all_sent:
    created = req.get('created_at', '')
    if created.startswith('2023-05-19T'):
        time_str = created.split('T')[1]  # e.g., "19:57:27"
        hour = int(time_str.split(':')[0])
        if hour >= 18:
            evening_requests.append(req)

print(f"Found {len(evening_requests)} evening requests")
for r in evening_requests:
    print(r)

